const u = $('Fällige Nutzer und Kontext laden').item.json;
const c = $input.item.json.content;
let roh = (Array.isArray(c) ? c : []).filter(b => b && b.type === 'text' && b.text).map(b => String(b.text)).join('\n').trim();
roh = roh.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const start = roh.indexOf('{');
const ende = roh.lastIndexOf('}');
const daten = JSON.parse(roh.slice(start, ende + 1));
const themen = (Array.isArray(daten.themen) ? daten.themen : []).slice(0, Math.min(5, Math.max(1, Number(u.anzahl) || 3))).map(t => ({
  titel: String(t.titel || '').trim(), aufhaenger: String(t.aufhaenger || '').trim(),
  idee: String(t.idee || '').trim(), quelle: String(t.quelle || '').trim()
})).filter(t => t.titel);
if (!themen.length) throw new Error('Keine Themen erzeugt');
return { json: { matrix_user_id: u.matrix_user_id, room_id: u.room_id, anzeigename: u.anzeigename, geplant: u.geplant, themen_json: JSON.stringify(themen) } };

// Chat-Layout (Vorgabe Stefan, 11.10.2026): Titel fett mit Doppelpunkt, Inhalt direkt darunter, Leerzeile zwischen Bloecken, keine Listenpunkte, keine Emojis
const esc = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const roh = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '');
const zeileHtml = z => typeof z === 'string' ? esc(z) : (z.html !== undefined ? z.html : (z.kursiv ? '<em>' + esc(z.t) + '</em>' : esc(z.t)));
const zeileText = z => typeof z === 'string' ? roh(z) : (z.behalten ? String(z.t ?? '') : roh(z.t));
const render = bloecke => {
  const b = bloecke.filter(x => x && (x.titel || (x.zeilen || []).length));
  return {
    html: b.map(x => (x.titel ? '<strong>' + esc(x.titel) + '</strong>' + ((x.zeilen || []).length ? '<br>' : '') : '') + (x.zeilen || []).map(zeileHtml).join('<br>')).join('<br><br>'),
    text: b.map(x => (x.titel ? roh(x.titel) + ((x.zeilen || []).length ? '\n' : '') : '') + (x.zeilen || []).map(zeileText).join('\n')).join('\n\n')
  };
};
const u = $('Antwort auslesen').item.json;
const s = $input.item.json;
const themen = Array.isArray(s.themen) ? s.themen : [];
const bloecke = [{ titel: 'Marketing-Themen für diese Woche:' }]
  .concat(themen.map(t => ({ titel: t.nr + '. ' + t.titel, zeilen: [{ t: '„' + t.aufhaenger + '“', kursiv: true }, t.idee] })))
  .concat([{ titel: 'Auswahl:', zeilen: ['Antworte direkt auf diese Nachricht mit den Nummern (z.B. „1 und 3“), dann bereite ich die Beiträge vor. Eigene Themen gehen auch, z.B. „Mach einen Beitrag zu …“.'] }]);
const n = render(bloecke);
return { json: { matrix_user_id: u.matrix_user_id, room_id: u.room_id, geplant: u.geplant, batch_id: s.batch_id, anzahl: themen.length, text: n.text, html: n.html } };

// KI-Budget-Sperre (Stefan 18.10.2026): keine Themenvorschlaege, nichts gespeichert, kein Fehlversuch. Ergebnis fuer Ally beim Start auf Zuruf.
const text = String($input.first().json.ki_sperre_text || '').trim() || 'Das KI-Budget für diesen Monat ist erreicht.';
return [{ json: { status: 'Keine Themenvorschläge erstellt', fehler: text } }];

